// Fiches de l'atlas qui ont une structure 3D (chantiers A.3 et C.3).
// clé = id de la fiche (MINERAUX ou ESPECES) → fichier structures/<fichier>.js + réglages d'affichage.
// Réglages possibles : mode ("billes" | "polyedres" | "compact"), polyedres (éléments centres),
// ligandsHors (false = seulement les atomes de la maille), decalage [fx, fy, fz] (origine déplacée), repetition [na, nb, nc],
// vue { axe: "a" | "b" | "c", inclinaison: [degrés autour de l'horizontale, de la verticale] }, note (texte affiché).
(function () {
  const KAOLINITE_H = "Structure affinée à 1,5 K, la seule de la COD à placer les hydrogènes. Entre cette température et l'ambiante, la maille ne varie que de 0,04 % (Bish et Von Dreele 1989).";
  const PLAGIO_MOYEN = "Dans la structure moyenne, sodium et calcium occupent un site commun, tout comme aluminium et silicium se partagent les tétraèdres. Le long de la série, Ca²⁺ + Al³⁺ prennent la place de Na⁺ + Si⁴⁺, de l'albite (NaAlSi₃O₈) à l'anorthite (CaAl₂Si₂O₈).";
  Structure3D.index({
    // ── silice ──
    quartz: { fichier: "quartz" },
    calcedoine: { fichier: "quartz",
      note: "La calcédoine est formée de fibres de quartz microscopiques, auxquelles s'ajoute un peu de moganite ; sa structure reste celle du quartz." },
    coesite: { fichier: "coesite" },

    // ── carbonates, sulfates, halogénures, phosphates ──
    calcite: { fichier: "calcite", polyedres: ["C", "Ca"] },
    aragonite: { fichier: "aragonite", polyedres: ["C"] },
    dolomite: { fichier: "dolomite", polyedres: ["C", "Ca", "Mg"] },
    siderite: { fichier: "siderite", polyedres: ["C", "Fe"] },
    halite_m: { fichier: "halite", ligandsHors: false, polyedres: ["Na"], decalage: [0.5, 0, 0] },
    sylvite: { fichier: "sylvite", ligandsHors: false },
    fluorine: { fichier: "fluorine" },
    chlorargyrite: { fichier: "chlorargyrite", ligandsHors: false,
      note: "Structure identique à celle du sel de cuisine, où chaque argent est entouré de six chlores disposés en cube. La liaison Ag-Cl, en partie covalente, confère au cristal une souplesse telle qu'on le taille au couteau." },
    carnallite: { fichier: "carnallite", polyedres: ["Mg"],
      note: "Chaque magnésium occupe le centre d'un octaèdre formé de six molécules d'eau, Mg(H₂O)₆, tandis que le potassium et le chlore comblent les intervalles entre ces octaèdres. Cette eau, retenue par des liaisons hydrogène fragiles, rend compte du fait que la carnallite se liquéfie dans l'air humide." },
    cryolite: { fichier: "cryolite", polyedres: ["Al"],
      note: "Les octaèdres AlF₆, isolés et faiblement inclinés les uns par rapport aux autres, sont séparés par des atomes de sodium : l'ensemble adopte un arrangement de type pérovskite, presque cubique. Au-delà de 885 °C, les octaèdres se redressent et la maille devient cubique." },
    atacamite: { fichier: "atacamite",
      note: "Le cuivre occupe le centre d'octaèdres allongés : 4 OH proches et 2 Cl plus lointains, ou bien 5 OH et 1 Cl. Ces octaèdres mettent leurs arêtes en commun pour former une charpente. Les positions sont celles des cations d'un spinelle (Parise et Hyde 1986)." },
    gypse_m: { fichier: "gypse", polyedres: ["S"] },
    anhydrite: { fichier: "anhydrite", polyedres: ["S"] },
    apatite: { fichier: "apatite", polyedres: ["P"],
      note: "Fluorapatite, Ca₅(PO₄)₃F : dans les apatites des roches, une partie du fluor cède sa place à OH⁻ et Cl⁻." },

    // ── feldspaths et feldspathoïdes ──
    orthose: { fichier: "orthose" },
    sanidine: { fichier: "sanidine" },
    microcline: { fichier: "microcline" },
    albite: { fichier: "albite" },
    anorthite: { fichier: "anorthite" },
    plagioclases: { fichier: "plagioclase_an48",
      note: "Plagioclase An48, à 48 % d'anorthite : structure moyenne, prise au milieu de la série." + PLAGIO_MOYEN },
    andesine: { fichier: "plagioclase_an48", note: "Plagioclase An48 (andésine). " + PLAGIO_MOYEN },
    labradorite: { fichier: "labradorite", note: "Plagioclase An62 à 66 (labradorite)." + PLAGIO_MOYEN },
    nepheline: { fichier: "nepheline" },
    leucite: { fichier: "leucite" },

    // ── olivine, grenats, silicates d'alumine ──
    forsterite: { fichier: "forsterite" },
    olivine: { fichier: "forsterite",
      note: "Forstérite (Mg₂SiO₄) : pôle magnésien de la série. Dans l'olivine courante, une partie du magnésium est occupée par le fer (Fe²⁺)." },
    grenat: { fichier: "almandin", mode: "polyedres", polyedres: ["Si", "Al"],
      note: "Structure de l'almandin, Fe₃Al₂(SiO₄)₃, grenat des micaschistes et des gneiss. Les autres grenats reprennent cette charpente : le magnésium, le calcium ou le manganèse remplacent le fer, tandis que le Fe³⁺ ou le Cr³⁺ prennent la place de l'aluminium." },
    almandin: { fichier: "almandin", mode: "polyedres", polyedres: ["Si", "Al"] },
    pyrope: { fichier: "pyrope", mode: "polyedres", polyedres: ["Si", "Al"] },
    grossulaire: { fichier: "grossulaire", mode: "polyedres", polyedres: ["Si", "Al"] },
    andradite: { fichier: "andradite", mode: "polyedres", polyedres: ["Si", "Fe"] },
    zircon: { fichier: "zircon", polyedres: ["Si"] },
    titanite: { fichier: "titanite", mode: "polyedres", polyedres: ["Si", "Ti"] },
    andalousite: { fichier: "andalousite", mode: "polyedres", polyedres: ["Si", "Al"] },
    sillimanite: { fichier: "sillimanite", mode: "polyedres", polyedres: ["Si", "Al"] },
    disthene: { fichier: "disthene", mode: "polyedres", polyedres: ["Si", "Al"] },
    topaze: { fichier: "topaze", mode: "polyedres", polyedres: ["Si", "Al"] },
    epidote: { fichier: "epidote", mode: "polyedres", polyedres: ["Si", "Al", "Fe"] },
    zoisite: { fichier: "zoisite", mode: "polyedres", polyedres: ["Si", "Al"] },
    clinozoisite: { fichier: "clinozoisite", mode: "polyedres", polyedres: ["Si", "Al"] },
    lawsonite: { fichier: "lawsonite", mode: "polyedres", polyedres: ["Si", "Al"] },
    beryl: { fichier: "beryl", mode: "polyedres", polyedres: ["Si", "Be"] },
    cordierite: { fichier: "cordierite", mode: "polyedres", polyedres: ["Si", "Al"] },
    tourmaline: { fichier: "tourmaline", mode: "polyedres", polyedres: ["Si", "B"] },

    // ── pyroxènes, amphiboles, pyroxénoïdes ──
    augite: { fichier: "augite", mode: "polyedres", polyedres: ["Si", "Mg"] },
    pyroxenes: { fichier: "augite", mode: "polyedres", polyedres: ["Si", "Mg"],
      note: "L'augite, pyroxène le plus répandu dans les basaltes et les gabbros, présente une structure faite de chaînes simples de tétraèdres SiO₄ reliées entre elles par des rubans d'octaèdres de magnésium et de fer." },
    diopside: { fichier: "diopside", mode: "polyedres", polyedres: ["Si", "Mg"] },
    enstatite: { fichier: "enstatite", mode: "polyedres", polyedres: ["Si", "Mg"],
      note: "Orthoenstatite pure (MgSiO₃) : dans l'orthopyroxène des roches, une partie du magnésium est remplacée par du fer." },
    omphacite: { fichier: "omphacite", mode: "polyedres", polyedres: ["Si", "Al", "Mg"] },
    aegyrine: { fichier: "aegyrine", mode: "polyedres", polyedres: ["Si", "Fe"] },
    jadeite: { fichier: "jadeite", mode: "polyedres", polyedres: ["Si", "Al"] },
    wollastonite: { fichier: "wollastonite", mode: "polyedres", polyedres: ["Si"] },
    hornblende: { fichier: "hornblende", mode: "polyedres", polyedres: ["Si", "Mg"] },
    amphiboles: { fichier: "hornblende", mode: "polyedres", polyedres: ["Si", "Mg"],
      note: "Hornblende magnésienne : les doubles chaînes de tétraèdres SiO₄ sont liées par des rubans d'octaèdres et portent des groupes OH." },
    pargasite: { fichier: "pargasite", mode: "polyedres", polyedres: ["Si", "Mg"] },
    tremolite: { fichier: "tremolite", mode: "polyedres", polyedres: ["Si", "Mg"] },
    actinote: { fichier: "actinote", mode: "polyedres", polyedres: ["Si", "Mg"] },
    glaucophane: { fichier: "glaucophane", mode: "polyedres", polyedres: ["Si", "Mg", "Al"] },
    arfvedsonite: { fichier: "arfvedsonite", mode: "polyedres", polyedres: ["Si", "Fe"] },

    // ── micas, chlorites, serpentines ──
    muscovite: { fichier: "muscovite", mode: "polyedres" },
    illite_m: { fichier: "muscovite", mode: "polyedres",
      note: "Aucune structure affinée n'existe pour l'illite : ses feuillets de mica dioctaédrique, moins riches en potassium, s'empilent sans ordre. La structure montrée est celle de la muscovite, dont elle se rapproche." },
    biotite: { fichier: "biotite", mode: "polyedres" },
    phlogopite: { fichier: "phlogopite", mode: "polyedres" },
    clinochlore: { fichier: "clinochlore", mode: "polyedres" },
    chlorite_m: { fichier: "clinochlore", mode: "polyedres",
      note: "Clinochlore, chlorite magnésienne la plus fréquente : un feuillet de mica dépourvu de potassium alterne avec une couche d'hydroxyde de magnésium." },
    lizardite: { fichier: "lizardite", mode: "polyedres" },
    serpentine: { fichier: "lizardite", mode: "polyedres",
      note: "La lizardite, serpentine aux feuillets plans, est décrite ici. L'antigorite, aux feuillets ondulés, et le chrysotile, aux feuillets enroulés en fibres, ne se laissent pas réduire à une maille élémentaire de petite taille." },

    // ── argiles ──
    kaolinite_m: { fichier: "kaolinite", mode: "polyedres", note: KAOLINITE_H },
    kaolinite_e: { fichier: "kaolinite", mode: "polyedres", note: KAOLINITE_H },
    dickite: { fichier: "dickite", mode: "polyedres" },
    gibbsite: { fichier: "gibbsite", mode: "polyedres", polyedres: ["Al"] },

    // ── oxydes, sulfures, éléments natifs ──
    magnetite: { fichier: "magnetite", mode: "polyedres", polyedres: ["Fe"] },
    chromite: { fichier: "chromite", mode: "polyedres", polyedres: ["Cr", "Fe"] },
    hematite: { fichier: "hematite", mode: "polyedres", polyedres: ["Fe"] },
    ilmenite: { fichier: "ilmenite", mode: "polyedres", polyedres: ["Fe", "Ti"] },
    goethite: { fichier: "goethite", mode: "polyedres", polyedres: ["Fe"] },
    rutile: { fichier: "rutile", mode: "polyedres", polyedres: ["Ti"], repetition: [2, 2, 2] },
    cassiterite: { fichier: "cassiterite", mode: "polyedres", polyedres: ["Sn"], repetition: [2, 2, 2] },
    pyrite: { fichier: "pyrite",
      note: "Chaque fer se trouve au centre d'un octaèdre de soufres, mais ceux-ci vont par paires (S₂, 2,16 Å). La structure reprend celle du sel de cuisine, des paires de soufre remplaçant le chlore, chacune couchée le long d'une diagonale du cube." },
    // ── inosilicates et phyllosilicates (F.4 classes IX.D, IX.E, 01/10/2026) ──
    ferrosilite: { fichier: "ferrosilite", polyedres: ["Si","Fe"],
      note: "Orthopyroxène ferreux : des chaînes simples de tétraèdres SiO₄, orientées selon c, sont reliées par les octaèdres M1 et les grands sites M2. La maille est orthorhombique, deux fois plus longue selon a." },
    hedenbergite: { fichier: "hedenbergite", polyedres: ["Si","Fe"],
      note: "Dans ce pyroxène, les tétraèdres SiO₄ forment des chaînes simples orientées selon c. Les octaèdres M1 et les grands sites M2 les relient ; le calcium occupe M2 et le fer ferreux M1." },
    pigeonite: { fichier: "pigeonite", polyedres: ["Si","Fe","Mg"],
      note: "Chaînes de tétraèdres SiO₄ alignées selon c, reliées par les octaèdres M1 et les grands sites M2. Pauvre en calcium, il voit une partie de M2 occupée par Fe et Mg, ce qui abaisse la symétrie (P2₁/c)." },
    johannsenite: { fichier: "johannsenite", polyedres: ["Si","Mn"],
      note: "Pyroxène : chaînes simples de tétraèdres SiO₄ orientées selon c, reliées par des rubans d'octaèdres (sites M1) et par de grands sites M2. Le calcium occupe les sites M2, le manganèse les sites M1." },
    kosmochlor: { fichier: "kosmochlor", polyedres: ["Si","Cr"],
      note: "Pyroxène : chaînes simples de tétraèdres SiO₄ orientées selon c, reliées par des rubans d'octaèdres (sites M1) et par de grands sites M2. Le sodium occupe les sites M2, le chrome les sites M1 ; produit de synthèse." },
    spodumene: { fichier: "spodumene", polyedres: ["Si","Al"],
      note: "Pyroxène : chaînes simples de tétraèdres SiO₄ orientées selon c, reliées par des rubans d'octaèdres (sites M1) et par de grands sites M2. Le lithium occupe les sites M2, l'aluminium les sites M1. Affinement par diffraction des neutrons." },
    rhodonite: { fichier: "rhodonite", polyedres: ["Si","Mn"],
      note: "Pyroxénoïde à chaînes simples dont le motif se répète tous les cinq tétraèdres ; octaèdres de manganèse accompagnés de calcium, de magnésium et de fer." },
    pectolite: { fichier: "pectolite", polyedres: ["Si"],
      note: "Pyroxénoïde à chaînes dont le motif revient tous les trois tétraèdres. Calcium et sodium s'intercalent ; une liaison hydrogène très courte unit deux chaînes voisines." },
    bustamite: { fichier: "bustamite", polyedres: ["Si","Mn"],
      note: "Pyroxénoïde à motif répété tous les trois tétraèdres, comme la wollastonite, avec du calcium et du manganèse." },
    anthophyllite: { fichier: "anthophyllite", polyedres: ["Si"],
      note: "Orthoamphibole : des doubles chaînes de tétraèdres, rubans Si₈O₂₂ orientés selon c, sont unies par des rubans d'octaèdres. Un OH occupe le centre de chaque anneau, et le site A reste souvent vide. Maille orthorhombique." },
    cummingtonite: { fichier: "cummingtonite", polyedres: ["Si"],
      note: "Amphibole : chaînes doubles de tétraèdres orientées selon c (rubans Si₈O₂₂), reliées par des rubans d'octaèdres, avec un groupement OH au centre de chaque anneau et un site A souvent vacant. Magnésium et fer occupent tous les sites, et le site A est vide." },
    grunerite: { fichier: "grunerite", polyedres: ["Si","Fe"],
      note: "Doubles chaînes de tétraèdres selon c (Si₈O₂₂), rubans d'octaèdres, OH au centre des anneaux et site A souvent inoccupé. Il s'agit du pôle ferreux de la cummingtonite." },
    kaersutite: { fichier: "kaersutite", polyedres: ["Si"],
      note: "Amphibole : chaînes doubles de tétraèdres orientées selon c (rubans Si₈O₂₂), reliées par des rubans d'octaèdres, avec un groupement OH au centre de chaque anneau et un site A souvent vacant. Ici, le titane occupe un octaèdre, l'oxygène se substitue à une partie des OH et le site A est occupé." },
    richterite: { fichier: "richterite", polyedres: ["Si","Mg"],
      note: "Amphibole : chaînes doubles de tétraèdres orientées selon c (rubans Si₈O₂₂), reliées par des rubans d'octaèdres, avec un groupement OH au centre de chaque anneau et un site A souvent vacant. Le sodium occupe le site M4 et le site A ; il s'agit ici d'une richtérite potassique de synthèse." },
    riebeckite: { fichier: "riebeckite", polyedres: ["Si","Fe"],
      note: "Amphibole : chaînes doubles de tétraèdres orientées selon c (rubans Si₈O₂₂), reliées par des rubans d'octaèdres, avec un groupement OH au centre de chaque anneau et un site A souvent vacant. Sodium en M4, fer ferreux et ferrique dans les octaèdres ; cristal naturel renfermant un peu de potassium et de fluor." },
    apophyllite: { fichier: "apophyllite", polyedres: ["Si"],
      note: "Les tétraèdres forment des anneaux de quatre et de huit, en feuillets reliés par le calcium et le potassium, avec de l'eau entre les feuillets. Fluorapophyllite partiellement déshydratée, étudiée aux neutrons." },
    prehnite: { fichier: "prehnite", polyedres: ["Si","Al"],
      note: "Des feuillets de tétraèdres (Si et Al) sont unis par des octaèdres d'aluminium et par du calcium : ce phyllosilicate a ainsi des feuillets solidaires, d'où un clivage seulement bon." },
    paragonite: { fichier: "paragonite", polyedres: ["Si"],
      note: "Mica dioctaédrique au sodium : des feuillets 2:1 d'aluminium encadrent du sodium (d(001) ≈ 9,6 Å)." },
    glauconie: { fichier: "glauconite", polyedres: ["Si"],
      note: "Mica dioctaédrique ferrifère et potassique (modèle de Drits et al. 2010 ; octaèdres notés Al)." },
    lepidolite: { fichier: "lepidolite", polyedres: ["Si"],
      note: "Mica trioctaédrique renfermant du lithium et de l'aluminium, le potassium s'intercalant entre les feuillets." },
    zinnwaldite: { fichier: "zinnwaldite", polyedres: ["Si"],
      note: "Mica trioctaédrique qui associe lithium, fer et aluminium." },
    margarite: { fichier: "margarite", polyedres: ["Si"],
      note: "Mica « cassant » : le calcium, deux fois plus chargé que le potassium, s'intercale entre les feuillets et les serre davantage. Étude aux neutrons." },
    clintonite: { fichier: "clintonite", polyedres: ["Si"],
      note: "Mica cassant de type trioctaédrique : du calcium entre les feuillets, et de l'aluminium jusque dans les tétraèdres." },
    talc: { fichier: "talc", polyedres: ["Si"],
      note: "Feuillets 2:1 au magnésium, électriquement neutres : aucun cation ne s'intercale, et seules des forces de van der Waals assurent la cohésion." },
    pyrophyllite: { fichier: "pyrophyllite", polyedres: ["Si"],
      note: "Feuillets 2:1 à l'aluminium, neutres, sans cation intercalé : c'est l'équivalent alumineux du talc." },
    antigorite: { fichier: "antigorite", polyedres: ["Si"],
      note: "Serpentine aux feuillets ondulés : la couche de magnésium, plus large que la couche de silice, l'oblige à s'incurver, puis à s'inverser tous les 21,75 Å (Capitani et Mellini 2004)." },
    chrysotile: { fichier: "lizardite", polyedres: ["Si"],
      note: "Le chrysotile, dont les feuillets s'enroulent en tubes, n'a pas de maille plane : la structure montrée est celle de la lizardite, au même feuillet posé à plat." },
    chamosite: { fichier: "chamosite", polyedres: ["Si"],
      note: "Chlorite ferreuse : des feuillets 2:1 alternent avec un feuillet d'hydroxyde, le fer se substituant au magnésium." },
    // ── sorosilicates et cyclosilicates (F.4 classes IX.B, IX.C, 01/10/2026) ──
    piemontite: { fichier: "piemontite", polyedres: ["Si"],
      note: "Épidote-groupe : des octaèdres s'alignent en chaînes selon b et sont liés à des tétraèdres SiO₄ isolés ainsi qu'à des paires Si₂O₇ ; le calcium loge dans les grandes cavités. Le manganèse trivalent, dans un site octaédrique, explique la couleur rouge." },
    allanite: { fichier: "allanite", polyedres: ["Si"],
      note: "Groupe de l'épidote : chaînes d'octaèdres orientées selon b, reliées par des tétraèdres SiO₄ isolés et des paires Si₂O₇, avec des calciums dans les grandes cavités. Une terre rare, le cérium, prend la place d'un calcium, et le fer celle de l'aluminium." },
    vesuvianite: { fichier: "vesuvianite", polyedres: ["Si"],
      note: "Tétraèdres SiO₄ et Si₂O₇, colonnes de calcium et de fer le long de c, sites à cinq oxygènes en pyramide ; hydrogènes placés (Lager et al. 1999)." },
    pumpellyite: { fichier: "pumpellyite", polyedres: ["Si"],
      note: "Des octaèdres s'enchaînent selon b et se relient par des tétraèdres SiO₄ et Si₂O₇. Cette espèce, parente de l'épidote, est davantage hydratée." },
    akermanite: { fichier: "akermanite", polyedres: ["Si","Mg"],
      note: "Dans la mélilite, des couches de tétraèdres (Si₂O₇ et un tétraèdre de Mg, Al ou Zn) s'empilent perpendiculairement à c, le calcium s'intercalant entre elles. Pôle magnésien." },
    gehlenite: { fichier: "gehlenite", polyedres: ["Al"],
      note: "Groupe de la mélilite : couches de tétraèdres (Si₂O₇ et un tétraèdre de Mg, Al ou Zn) perpendiculaires à c, séparées par des calciums. Pôle alumineux : aluminium et silicium se partagent les tétraèdres (sites partagés)." },
    hardystonite: { fichier: "hardystonite", polyedres: ["Si","Zn"],
      note: "Groupe de la mélilite : couches de tétraèdres (Si₂O₇ et un tétraèdre de Mg, Al ou Zn) perpendiculaires à c, séparées par des calciums. Ici, le zinc occupe les tétraèdres de liaison." },
    hemimorphite: { fichier: "hemimorphite", polyedres: ["Si","Zn"],
      note: "Les tétraèdres ZnO₃(OH) et les paires Si₂O₇ pointent tous dans le même sens selon c, ce qui rend le cristal polaire : ses deux extrémités diffèrent, d'où son nom. Hydrogènes placés (neutrons)." },
    bertrandite: { fichier: "bertrandite", polyedres: ["Si","Be"],
      note: "Charpente faite de tétraèdres BeO₃(OH) et de paires Si₂O₇, orientés selon c. Hydrogènes placés (neutrons)." },
    ilvaite: { fichier: "ilvaite", polyedres: ["Si"],
      note: "Des doubles chaînes d'octaèdres de fer, Fe²⁺ et Fe³⁺, s'étendent selon c et sont reliées par des paires Si₂O₇ ; le calcium et le manganèse occupent les cavités. Hydrogène placé." },
    thortveitite: { fichier: "thortveitite", polyedres: ["Si","Sc"],
      note: "Des feuillets d'octaèdres de scandium sont reliés par des paires Si₂O₇ dont l'oxygène médian occupe un centre de symétrie (angle Si-O-Si de 180°)." },
    cuspidine: { fichier: "cuspidine", polyedres: ["Si"],
      note: "Des polyèdres de calcium forment des chaînes, unies par des paires Si₂O₇. Le fluor n'est lié qu'au calcium." },
    tilleyite: { fichier: "tilleyite", polyedres: ["Si","C"],
      note: "Des calciums relient entre elles des paires Si₂O₇ et des triangles CO₃." },
    rankinite: { fichier: "rankinite", polyedres: ["Si"],
      note: "Paires Si₂O₇ isolées, reliées par des calciums." },
    axinite: { fichier: "axinite", polyedres: ["Si","B"],
      note: "Des groupes Si₂O₇ sont reliés deux à deux par des triangles de bore, des octaèdres d'aluminium et de fer, et du calcium : la charpente, triclinique, ne possède aucun plan de symétrie. Ferroaxinite du Mexique." },
    benitoite: { fichier: "benitoite", polyedres: ["Si","Ti"],
      note: "Les octaèdres TiO₆ relient des anneaux de trois tétraèdres (Si₃O₉) ; le baryum remplit les cavités. Seule espèce minérale de la classe 6̄m2." },
    wadeite: { fichier: "wadeite", polyedres: ["Si","Zr"],
      note: "Anneaux Si₃O₉ à trois tétraèdres, reliés par des octaèdres ZrO₆, le potassium logeant dans les cavités. Produit de synthèse." },
    catapleiite: { fichier: "catapleiite", polyedres: ["Si","Zr"],
      note: "Anneaux à trois tétraèdres, unis par des octaèdres ZrO₆ ; le sodium et l'eau logent dans les cavités, dont l'eau n'est pas représentée." },
    joaquinite: { fichier: "joaquinite", polyedres: ["Si"],
      note: "Couches d'anneaux de quatre tétraèdres (Si₄O₁₂), liées par des octaèdres de titane ; baryum et terres rares s'intercalent entre ces couches." },
    baotite: { fichier: "baotite", polyedres: ["Si","Ti"],
      note: "Des anneaux Si₄O₁₂ et des colonnes d'octaèdres de titane et de niobium composent la charpente ; le baryum et le chlore occupent les canaux." },
    bazzite: { fichier: "bazzite", polyedres: ["Si","Be"],
      note: "Structure du béryl, où le scandium remplace l'aluminium : des anneaux Si₆O₁₈ s'empilent en canaux selon c." },
    sekaninaite: { fichier: "sekaninaite", polyedres: ["Si","Al"],
      note: "Structure de type cordiérite, le fer remplaçant le magnésium : des anneaux de six tétraèdres, où Si et Al sont ordonnés, s'empilent en canaux." },
    indialite: { fichier: "indialite", polyedres: ["Si","Al"],
      note: "Hexagonale, cette cordiérite présente Si et Al désordonnés dans les anneaux ; le cristal provient d'une enclave du Vésuve." },
    dravite: { fichier: "dravite", polyedres: ["Si","B"],
      note: "Dans le groupe de la tourmaline, des anneaux de six tétraèdres SiO₄ pointent tous selon c, ce qui rend le cristal polaire. S'y ajoutent des triangles BO₃ et des octaèdres ; le magnésium occupe les sites Y : c'est le pôle magnésien." },
    elbaite: { fichier: "elbaite", polyedres: ["Si","B"],
      note: "Anneaux de six tétraèdres SiO₄ alignés selon c (cristal polaire), accompagnés de triangles BO₃ et d'octaèdres. Lithium et aluminium se partagent les sites Y. Hydrogènes placés (neutrons)." },
    uvite: { fichier: "uvite", polyedres: ["Si","B"],
      note: "Des anneaux SiO₄ à six tétraèdres, pointés selon c, forment un cristal polaire avec des triangles BO₃ et des octaèdres. Calcium en site X, magnésium en sites Y." },
    liddicoatite: { fichier: "liddicoatite", polyedres: ["Si","B"],
      note: "Anneaux de six tétraèdres SiO₄, tous orientés selon c, cristal polaire ; triangles BO₃ et octaèdres complètent la structure. Calcium en X, lithium et aluminium en Y. Cristal de Madagascar." },
    dioptase: { fichier: "dioptase", polyedres: ["Si"],
      note: "Des anneaux Si₆O₁₈ à six tétraèdres sont reliés par des cuivres disposés en carré, et des molécules d'eau forment des anneaux dans les canaux. Hydrogènes placés." },
    milarite: { fichier: "milarite", polyedres: ["Si"],
      note: "Dans le groupe de la milarite, des doubles anneaux de douze tétraèdres (Si₁₂O₃₀) s'empilent selon c. Octaèdres et gros cations les relient ; le béryllium occupe les tétraèdres de liaison." },
    osumilite: { fichier: "osumilite", polyedres: ["Si"],
      note: "Groupe de la milarite : doubles anneaux de douze tétraèdres (Si₁₂O₃₀) empilés selon c, unis par des octaèdres et de gros cations ; magnésium, fer et aluminium occupent les sites de liaison." },
    sugilite: { fichier: "sugilite", polyedres: ["Si"],
      note: "Groupe de la milarite : doubles anneaux de douze tétraèdres (Si₁₂O₃₀) empilés selon c, reliés par des octaèdres et de gros cations ; lithium et fer occupent les sites de liaison, et le manganèse donne aux sugilites gemmes leur couleur violette." },
    roedderite: { fichier: "roedderite", polyedres: ["Si"],
      note: "Groupe de la milarite : doubles anneaux de douze tétraèdres (Si₁₂O₃₀) empilés selon c, unis par des octaèdres et de gros cations ; le magnésium occupe les sites de liaison. Cristal provenant d'une lamproïte espagnole." },
    eudialyte: { fichier: "eudialyte", polyedres: ["Si","Zr"],
      note: "Sodium partout, ce cristal (558 atomes par maille) combine anneaux de trois et de neuf tétraèdres, octaèdres de zirconium et anneaux de six octaèdres de calcium." },
    // ── nésosilicates (F.4 classe IX.A, 01/10/2026) ──
    phenacite: { fichier: "phenacite", polyedres: ["Si","Be"],
      note: "Une charpente percée de canaux selon c se forme lorsque des tétraèdres SiO₄ et BeO₄ se relient par leurs sommets (structure de la willémite)." },
    willemite: { fichier: "willemite", polyedres: ["Si","Zn"],
      note: "Par leurs sommets, des tétraèdres SiO₄ et ZnO₄ forment une charpente traversée de canaux selon c." },
    eucryptite: { fichier: "eucryptite", polyedres: ["Si"],
      note: "Structure de la phénacite, où Li et Al remplacent le béryllium : charpente de tétraèdres dans laquelle Al et Si occupent les mêmes sites (structure moyenne)." },
    fayalite: { fichier: "fayalite", polyedres: ["Si","Fe"],
      note: "Tétraèdres SiO₄ isolés, et deux sites octaédriques organisés en chaînes selon c : c'est le pôle ferreux de l'olivine (Fe₂SiO₄)." },
    tephroite: { fichier: "tephroite", polyedres: ["Si","Mn"],
      note: "Tétraèdres SiO₄ isolés ; deux sites octaédriques s'enchaînent selon c. Ce terme est le pôle manganésifère (Mn₂SiO₄)." },
    liebenbergite: { fichier: "liebenbergite", polyedres: ["Si","Ni"],
      note: "Chaînes d'octaèdres selon c et tétraèdres SiO₄ isolés : pôle nickélifère (Ni₂SiO₄), produit de synthèse." },
    monticellite: { fichier: "monticellite", polyedres: ["Si","Mg"],
      note: "Octaèdres en chaînes selon c, et tétraèdres SiO₄ isolés. Plus volumineux, le calcium occupe un site sur deux, le magnésium occupant l'autre." },
    kirschsteinite: { fichier: "kirschsteinite", polyedres: ["Si","Fe"],
      note: "Chaînes d'octaèdres selon c et tétraèdres SiO₄ isolés. Les deux sites sont partagés entre calcium et fer ; cristal de météorite (angrite)." },
    glaucochroite: { fichier: "glaucochroite", polyedres: ["Si","Mn"],
      note: "Chaînes d'octaèdres selon c, tétraèdres SiO₄ isolés. Calcium et manganèse se répartissent entre les deux sites." },
    larsenite: { fichier: "larsenite", polyedres: ["Si","Zn"],
      note: "Tétraèdres SiO₄ et ZnO₄ ; les plombs sont entourés d'oxygènes d'un seul côté, à cause de leur doublet électronique libre." },
    wadsleyite: { fichier: "wadsleyite", polyedres: ["Si","Mg"],
      note: "Entre 410 et 525 km, l'olivine change de forme : ses tétraèdres SiO₄ se groupent par paires (Si₂O₇), et un oxygène sur huit reste sans silicium, ce qui permet d'accueillir de l'eau." },
    ringwoodite: { fichier: "ringwoodite", polyedres: ["Si","Mg"],
      note: "À très haute pression (525 à 660 km), l'olivine adopte une structure de spinelle : silicium en tétraèdres, magnésium en octaèdres, oxygènes en empilement cubique compact." },
    spessartine: { fichier: "spessartine", polyedres: ["Si","Al"],
      note: "Dans le grenat, les tétraèdres SiO₄ isolés sont liés par des octaèdres (Al, Cr, Fe³⁺, V, Ti), tandis que les sites à huit oxygènes, en cube déformé, accueillent Ca, Mg, Fe²⁺ ou Mn. Ici, le manganèse occupe ces sites." },
    knorringite: { fichier: "knorringite", polyedres: ["Si","Cr"],
      note: "Tétraèdres SiO₄ isolés, octaèdres (Al, Cr, Fe³⁺, V, Ti) et sites cubiques déformés (Ca, Mg, Fe²⁺, Mn) : le chrome occupe les octaèdres, le magnésium les sites cubiques. Produit synthétique." },
    uvarovite: { fichier: "uvarovite", polyedres: ["Si","Cr"],
      note: "Charpente à tétraèdres SiO₄ isolés, octaèdres (Al, Cr, Fe³⁺, V, Ti) et sites cubiques (Ca, Mg, Fe²⁺, Mn). Le chrome se trouve dans les octaèdres, le calcium dans les sites cubiques ; cristal naturel." },
    goldmanite: { fichier: "goldmanite", polyedres: ["Si","V"],
      note: "Le vanadium occupe les octaèdres ; des tétraèdres SiO₄ isolés et des sites cubiques déformés (Ca, Mg, Fe²⁺, Mn) complètent la charpente, avec les octaèdres (Al, Cr, Fe³⁺, V, Ti). Produit synthétique." },
    schorlomite: { fichier: "schorlomite", polyedres: ["Si","Ti"],
      note: "Structure : tétraèdres SiO₄ isolés, octaèdres (Al, Cr, Fe³⁺, V, Ti) et sites cubiques (Ca, Mg, Fe²⁺, Mn). Le titane occupe les octaèdres, et le fer s'étend jusque dans les tétraèdres." },
    hydrogrossulaire: { fichier: "hydrogrossulaire", polyedres: ["Si","Al"],
      note: "Dans la katoïte, une partie des tétraèdres SiO₄ est remplacée par quatre OH (sites en partie vides, hydrogènes non placés). Charpente : tétraèdres SiO₄ isolés, octaèdres (Al, Cr, Fe³⁺, V, Ti) et sites cubiques (Ca, Mg, Fe²⁺, Mn)." },
    majorite: { fichier: "majorite", polyedres: ["Si","Al"],
      note: "Dans ce grenat du manteau profond, le silicium occupe aussi des octaèdres ; tétraèdres SiO₄, octaèdres (Al, Cr, Fe³⁺, V, Ti) et sites cubiques (Ca, Mg, Fe²⁺, Mn) forment la charpente. Terme synthétique de la série majorite-pyrope." },
    hafnon: { fichier: "hafnon", polyedres: ["Si"],
      note: "Structure de type zircon : tétraèdres SiO₄ isolés et gros cations entourés de huit oxygènes, alignés selon c. Le hafnium remplace ici le zirconium ; produit synthétique." },
    thorite: { fichier: "thorite", polyedres: ["Si"],
      note: "Structure de type zircon : tétraèdres SiO₄ isolés et gros cations entourés de huit oxygènes, en chaînes selon c. Le thorium y remplace le zirconium ; produit de synthèse." },
    huttonite: { fichier: "huttonite", polyedres: ["Si"],
      note: "Même formule que la thorite, mais structure de la monazite : le thorium est entouré de neuf oxygènes." },
    coffinite: { fichier: "coffinite", polyedres: ["Si"],
      note: "Structure du zircon : tétraèdres SiO₄ isolés et gros cations entourés de huit oxygènes, en chaînes le long de c. Uranium à la place du zirconium ; synthétique (1958)." },
    mullite: { fichier: "mullite", polyedres: ["Al","Si"],
      note: "Des octaèdres AlO₆ s'enchaînent selon c, avec des tétraèdres où Al et Si se mêlent. Certains oxygènes font défaut, les sites n'étant qu'en partie occupés." },
    euclase: { fichier: "euclase", polyedres: ["Si","Al","Be"],
      note: "Couches de tétraèdres SiO₄ et BeO₃(OH) associées à des octaèdres d'aluminium ; le clivage parfait {010} sépare les couches." },
    staurotide: { fichier: "staurotide", polyedres: ["Si","Al"],
      note: "Des couches de type disthène (Al₂SiO₅) alternent avec des couches d'hydroxyde de fer et d'aluminium, perpendiculaires à a. La staurotide ressemble ainsi à un disthène feuilleté." },
    norbergite: { fichier: "norbergite", polyedres: ["Si","Mg"],
      note: "Dans le groupe de la humite, des tranches d'olivine alternent avec des couches de brucite où F et OH prennent la place de l'oxygène. Norbergite : une tranche d'olivine pour une couche de brucite. Hydrogènes placés." },
    chondrodite: { fichier: "chondrodite", polyedres: ["Si","Mg"],
      note: "Dans l'humite, une couche Mg(F,OH)₂ est encadrée par deux tranches d'olivine. Hydrogènes placés (neutrons)." },
    humite: { fichier: "humite", polyedres: ["Si","Mg"],
      note: "Dans le groupe de la humite, trois tranches d'olivine se succèdent autour d'une couche Mg(F,OH)₂." },
    clinohumite: { fichier: "clinohumite", polyedres: ["Si","Mg"],
      note: "Quatre tranches d'olivine s'empilent autour d'une couche Mg(F,OH)₂, selon le groupe de la humite. Hydrogènes placés (neutrons)." },
    alleghanyite: { fichier: "alleghanyite", polyedres: ["Si"],
      note: "Chondrodite : le manganèse remplace une partie du magnésium." },
    malayaite: { fichier: "malayaite", polyedres: ["Si","Sn"],
      note: "Structure de type titanite : chaînes d'octaèdres SnO₆ unies par l'intermédiaire de tétraèdres SiO₄, avec des calciums logés dans les cavités." },
    chloritoide: { fichier: "chloritoide", polyedres: ["Si","Al"],
      note: "Des couches d'octaèdres d'aluminium alternent avec des couches d'octaèdres de fer, de magnésium et d'aluminium, le tout relié par des tétraèdres SiO₄ isolés : il s'agit d'un faux mica cassant." },
    datolite: { fichier: "datolite", polyedres: ["Si","B"],
      note: "Couches alternées de tétraèdres SiO₄ et de BO₃(OH), reliées par le calcium. Hydrogènes placés." },
    dumortierite: { fichier: "dumortierite", polyedres: ["Si","Al"],
      note: "Octaèdres d'aluminium en chaînes selon a, associés à des tétraèdres SiO₄ et des triangles BO₃. Ce cristal est riche en antimoine et en arsenic, qui se partagent les sites." },
    kornerupine: { fichier: "kornerupine", polyedres: ["Si","Al"],
      note: "Octaèdres d'aluminium et de magnésium en chaînes selon c, reliés par des groupes Si₂O₇ et SiO₄ ; le silicium peut être en partie remplacé par du bore." },
    grandidierite: { fichier: "grandidierite", polyedres: ["Si","Al","B"],
      note: "Octaèdres d'aluminium en chaînes selon c, auxquels s'ajoutent des tétraèdres SiO₄, des triangles BO₃ et des magnésiums en bipyramides." },
    gadolinite: { fichier: "gadolinite", polyedres: ["Si","Be"],
      note: "Couches de tétraèdres SiO₄ et BeO₄ liées par des octaèdres de fer ; l'yttrium, terre rare, occupe les espaces entre les couches." },
    britholite: { fichier: "britholite", polyedres: ["Si"],
      note: "Structure de l'apatite : les tétraèdres SiO₄ remplacent les PO₄, et le cérium, terre rare, prend la place du calcium ; la symétrie s'abaisse en monoclinique." },
    ottrelite: { fichier: "chloritoide", polyedres: ["Si", "Al"],
      note: "Aucune structure affinée n'existe pour l'ottrélite : on lui attribue celle du chloritoïde, dont elle constitue le pôle manganésifère." },
    // ── oxydes et hydroxydes (F.4 classe IV, 01/10/2026) ──
    ferrihydrite: { fichier: "ferrihydrite", polyedres: ["Fe"],
      note: "Modèle de Michel et al. (2007) : nanocristaux de 2 à 6 nm, fers surtout en octaèdres et un sur cinq en tétraèdre, sites en partie vides. Une maille ne décrit qu'imparfaitement un cristal si petit." },
    lepidocrocite: { fichier: "lepidocrocite", polyedres: ["Fe"],
      note: "Des octaèdres FeO₆ ondulés, perpendiculaires à b, partagent leurs arêtes et restent liés par des liaisons hydrogène : d'où le débit en écailles. Hydrogènes placés (diffraction d'électrons)." },
    maghemite: { fichier: "maghemite", polyedres: ["Fe"],
      note: "Structure de type magnétite (spinelle) dans laquelle un site octaédrique sur six reste vide, tout le fer étant ferrique. Ces lacunes s'ordonnent et abaissent la symétrie (P4₃32)." },
    akaganeite: { fichier: "akaganeite", polyedres: ["Fe"],
      note: "Des doubles chaînes d'octaèdres FeO₆ délimitent des tunnels carrés (2 × 2) ; les chlores, logés dans ces tunnels, en assurent la cohésion. Akaganéite d'une météorite (Post et Buchwald 1991)." },
    wustite: { fichier: "wustite", polyedres: ["Fe"],
      note: "Chaque fer se loge au centre d'un octaèdre d'oxygènes, comme dans la structure du sel. La wüstite naturelle manque toujours un peu de fer (Fe₀,₉₅O) ; l'échantillon est presque stœchiométrique." },
    birnessite: { fichier: "birnessite", polyedres: ["Mn"],
      note: "Plan d'eau et de sodium, espacés d'environ 7 Å, séparent des feuillets d'octaèdres MnO₆ (sites vides et Mn³⁺). Birnessite sodique de synthèse (Post et Veblen 1990)." },
    lithiophorite: { fichier: "lithiophorite", polyedres: ["Mn","Al"],
      note: "Des feuillets d'octaèdres de manganèse alternent avec des feuillets d'octaèdres d'aluminium et de lithium, de type gibbsite ; des liaisons hydrogène les unissent." },
    todorokite: { fichier: "todorokite", polyedres: ["Mn"],
      note: "Murs de trois octaèdres MnO₆ délimitant des tunnels de 3 × 3, pleins d'eau et de cations (non placés)." },
    cryptomelane: { fichier: "cryptomelane", polyedres: ["Mn"],
      note: "Dans la hollandite, des doubles chaînes d'octaèdres MnO₆ forment des tunnels de 2 × 2 octaèdres, où loge le potassium, accompagné d'un peu de sodium et de strontium." },
    romanechite: { fichier: "romanechite", polyedres: ["Mn"],
      note: "Des tunnels de 2 × 3 octaèdres MnO₆ abritent le baryum et l'eau (eau non représentée ; le site du baryum n'est occupé qu'au tiers)." },
    pyrolusite: { fichier: "pyrolusite", polyedres: ["Mn"],
      note: "Structure du rutile : chaînes d'octaèdres MnO₆ partageant leurs arêtes le long de c — tunnels de 1 × 1, trop étroits pour un cation. Affinement aux neutrons (Bolzan et al. 1993)." },
    manganite: { fichier: "manganite", polyedres: ["Mn"],
      note: "Octaèdres de Mn³⁺ très déformés (effet Jahn-Teller : deux liaisons longues), en chaînes ; hydrogènes placés (Kohler et al. 1997)." },
    hausmannite: { fichier: "hausmannite", polyedres: ["Mn"],
      note: "Spinelle déformé : Mn²⁺ occupe les tétraèdres, et Mn³⁺ les octaèdres allongés (effet Jahn-Teller), ce qui donne une maille quadratique." },
    braunite: { fichier: "braunite", polyedres: ["Mn","Si"],
      note: "Une bixbyite modifiée : des octaèdres de Mn³⁺ voisinent avec des polyèdres de Mn²⁺ et un tétraèdre SiO₄, pour huit manganèses." },
    bixbyite: { fichier: "bixbyite", polyedres: ["Fe"],
      note: "Fluorine privée d'un oxygène sur quatre : chaque métal reste entouré de six oxygènes, et le fer et le manganèse partagent les sites (Fe₁,₂₆Mn₀,₇₄O₃)." },
    manganosite: { fichier: "manganosite", polyedres: ["Mn"],
      note: "Octaèdres d'oxygènes : chacun contient un manganèse en son centre, comme dans le sel." },
    fougerite: { fichier: "fougerite", polyedres: ["Fe"],
      note: "Seul le feuillet de type brucite est affiché (fer en octaèdres d'OH, Fe²⁺ et Fe³⁺ mêlés) : l'eau et les anions entre les feuillets, très désordonnés, ne sont occupés qu'à 8 % dans ce modèle (Trolard et al. 2007)." },
    bayerite: { fichier: "bayerite", polyedres: ["Al"],
      note: "Même feuillet d'octaèdres Al(OH)₆ que la gibbsite, mais empilé autrement : les OH d'un feuillet se logent dans les creux du suivant. Hydrogènes placés." },
    nordstrandite: { fichier: "nordstrandite", polyedres: ["Al"],
      note: "Il existe un troisième empilement des feuillets, mélange des deux arrangements de la gibbsite et de la bayérite ; les hydrogènes ne sont pas placés." },
    boehmite: { fichier: "boehmite", polyedres: ["Al"],
      note: "Ondulées et perpendiculaires à b, des doubles couches d'octaèdres AlO₄(OH)₂ tiennent par des liaisons hydrogène (cet affinement ne place pas les hydrogènes)." },
    diaspore: { fichier: "diaspore", polyedres: ["Al"],
      note: "Structure de type goethite : doubles chaînes d'octaèdres Al(O,OH)₆ selon c, plus serrées que dans la boehmite. Hydrogènes placés." },
    corindon: { fichier: "corindon", polyedres: ["Al"],
      note: "Empilement hexagonal compact d'oxygènes : l'aluminium occupe deux vides octaédriques sur trois. Liaisons courtes et serrées : c'est le minéral le plus dur après le diamant." },
    anatase: { fichier: "anatase", polyedres: ["Ti"],
      note: "Octaèdres TiO₆ partageant quatre arêtes chacun, en zigzag : il en résulte une maille quadratique très allongée (c ≈ 2,5 a)." },
    brookite: { fichier: "brookite", polyedres: ["Ti"],
      note: "Troisième arrangement du TiO₂, orthorhombique : des octaèdres TiO₆ partagent trois arêtes." },
    perovskite: { fichier: "perovskite", polyedres: ["Ti"],
      note: "Octaèdres TiO₆ reliés par leurs sommets dans les trois directions, le calcium occupant les grandes cavités ; légèrement basculés, ils donnent une maille orthorhombique presque cubique." },
    geikielite: { fichier: "geikielite", polyedres: ["Ti","Mg"],
      note: "Structure de l'ilménite : un dérivé du corindon où magnésium et titane alternent par plans." },
    cuprite: { fichier: "cuprite",
      note: "Oxygènes en réseau cubique centré : chaque cuivre est relié à deux oxygènes alignés, et deux réseaux pareils s'interpénètrent sans contact." },
    tenorite: { fichier: "tenorite",
      note: "Cuivre (Cu²⁺) entouré de quatre oxygènes en carré presque plan, en chaînes zigzagantes." },
    zincite: { fichier: "zincite", polyedres: ["Zn"],
      note: "Structure de la würtzite : chaque zinc se trouve au centre d'un tétraèdre d'oxygènes, tous orientés dans le même sens selon c (cristal polaire)." },
    gahnite: { fichier: "gahnite", polyedres: ["Zn","Al"],
      note: "Dans ce spinelle, le zinc occupe les tétraèdres et l'aluminium les octaèdres." },
    franklinite: { fichier: "franklinite", polyedres: ["Zn","Fe"],
      note: "Dans ce spinelle, le zinc occupe les tétraèdres et le fer ferrique les octaèdres. Ferrite de zinc de synthèse ; la franklinite naturelle contient aussi du manganèse." },
    eskolaite: { fichier: "eskolaite", polyedres: ["Cr"],
      note: "Structure du corindon, où le chrome remplace l'aluminium." },
    periclase: { fichier: "periclase", polyedres: ["Mg"],
      note: "Dans la structure du sel, un magnésium occupe le centre de chaque octaèdre d'oxygènes." },
    brucite: { fichier: "brucite", polyedres: ["Mg"],
      note: "Octaèdres Mg(OH)₆ en feuillets (type CdI₂), liés faiblement : clivage basal parfait. Hydrogènes placés." },
    spinelle: { fichier: "spinelle", polyedres: ["Mg","Al"],
      note: "Modèle de toute une famille : les oxygènes forment un empilement cubique compact, le magnésium occupe un huitième des vides tétraédriques et l'aluminium la moitié des vides octaédriques." },
    baddeleyite: { fichier: "baddeleyite", polyedres: ["Zr"],
      note: "Chaque zirconium est entouré de sept oxygènes : il s'agit d'une fluorine déformée et monoclinique." },
    uraninite: { fichier: "uraninite",
      note: "Uraniums en réseau cubique à faces centrées et oxygènes dans tous les vides tétraédriques : c'est la fluorine. La pechblende naturelle est partiellement oxydée et désordonnée." },
    thorianite: { fichier: "thorianite",
      note: "Structure de la fluorine, où le thorium remplace l'uranium : les deux minéraux forment une série." },
    columbite: { fichier: "columbite", polyedres: ["Nb","Fe"],
      note: "Dans l'ordre fer, niobium, niobium, des octaèdres de niobium et de fer forment des chaînes en zigzag selon c : une wolframite dédoublée." },
    pyrochlore: { fichier: "pyrochlore", polyedres: ["Nb"],
      note: "Octaèdres NbO₆ liés par leurs sommets ; calcium, sodium et fluor logent dans les cavités." },
    // ── phosphates, arséniates, vanadates (F.4 classe VIII, 01/10/2026) ──
    monazite: { fichier: "monazite", polyedres: ["P"],
      note: "Tétraèdres PO₄ isolés et gros ions de terres rares (ici le cérium) entourés de neuf oxygènes. Monazite-(Ce) naturelle (Ni et al. 1995)." },
    xenotime: { fichier: "xenotime", polyedres: ["P"],
      note: "Tétraèdres PO₄ et yttriums à huit oxygènes, en chaînes selon c : structure du zircon." },
    amblygonite: { fichier: "amblygonite", polyedres: ["P", "Al"],
      note: "Lithium logé entre des chaînes d'octaèdres d'aluminium reliées par des tétraèdres PO₄. Montebrasite (pôle à OH) mesurée à 22 °C ; hydrogène placé." },
    variscite: { fichier: "variscite", polyedres: ["P", "Al"],
      note: "Octaèdres AlO₄(H₂O)₂ et tétraèdres PO₄ en charpente, tenue aussi par les liaisons hydrogène des deux eaux. Hydrogènes placés (Kniep et al. 1977)." },
    strengite: { fichier: "strengite", polyedres: ["P", "Fe"],
      note: "Structure de la variscite, où le fer ferrique remplace l'aluminium : octaèdres FeO₄(H₂O)₂ et tétraèdres PO₄ forment la charpente. Hydrogènes placés (Taxer et Bartl 2004)." },
    vivianite: { fichier: "vivianite", polyedres: ["P", "Fe"],
      note: "Fer en octaèdres isolés ou par paires, reliés par des tétraèdres PO₄ en feuillets perpendiculaires à b ; eau et liaisons hydrogène entre eux. Maille I2/m (Bartl 1989), hydrogènes placés." },
    turquoise: { fichier: "turquoise", polyedres: ["P", "Al"],
      note: "Dans la turquoise naturelle, le site du cuivre est occupé à 90 % (Kolitsch et Giester 2000). Octaèdres d'aluminium, tétraèdres PO₄ et cuivres se lient à des OH et à de l'eau." },
    wavellite: { fichier: "wavellite", polyedres: ["P", "Al"],
      note: "Eau dans les canaux ; chaînes d'octaèdres d'aluminium (OH et fluor) reliées par des tétraèdres PO₄. Wavellite de Zbirov (Bohême)." },
    autunite: { fichier: "autunite", polyedres: ["P", "U"],
      note: "Des feuillets d'uranyle (UO₂²⁺, deux oxygènes à 1,8 Å de l'uranium) et des tétraèdres PO₄, perpendiculaires à b, sont séparés par du calcium et de l'eau. Autunite de synthèse (Locock et Burns 2003)." },
    torbernite: { fichier: "torbernite", polyedres: ["P", "U"],
      note: "Cuivre et eau entre des feuillets d'uranyle-phosphate identiques à ceux de l'autunite, mais perpendiculaires à c." },
    pyromorphite: { fichier: "pyromorphite", polyedres: ["P"],
      note: "Tétraèdres PO₄ ; autour de canaux hexagonaux où s'alignent les chlores, les plombs prennent place (structure de l'apatite)." },
    mimetite: { fichier: "mimetite", polyedres: ["As"],
      note: "Des tétraèdres AsO₄ remplacent les PO₄ dans cette apatite." },
    vanadinite: { fichier: "vanadinite", polyedres: ["V"],
      note: "Dans cette apatite, des tétraèdres VO₄ prennent la place des PO₄." },
    erythrite: { fichier: "erythrite", polyedres: ["As", "Co"],
      note: "Structure de la vivianite : octaèdres de cobalt reliés par des tétraèdres AsO₄ en feuillets, avec de l'eau entre ceux-ci." },
    // ── borates (F.4 classe VI, 01/10/2026) ──
    borax: { fichier: "borax", polyedres: ["B", "Na"],
      note: "Chaînes d'octaèdres Na(H₂O)₆ et ions borate [B₄O₅(OH)₄]²⁻, ces derniers formés de deux triangles BO₃ et deux tétraèdres BO₄ en anneau double. Hydrogènes placés (neutrons)." },
    kernite: { fichier: "kernite", polyedres: ["B"],
      note: "Reliés en longues chaînes selon b, triangles BO₃ et tétraèdres BO₄ enserrent du sodium et de l'eau (hydrogènes non placés par cet affinement)." },
    ulexite: { fichier: "ulexite", polyedres: ["B"],
      note: "Des chaînes d'octaèdres de sodium et de calcium, toutes allongées selon c, portent les fibres ; les ions borate isolés comptent trois tétraèdres et deux triangles." },
    colemanite: { fichier: "colemanite", polyedres: ["B"],
      note: "Des calciums relient des chaînes infinies de triangles BO₃ et de tétraèdres BO₄, orientées selon a ; hydrogènes placés (Burns et Hawthorne 1993)." },
    boracite: { fichier: "boracite", polyedres: ["B"],
      note: "Magnésium et chlore occupent les cages d'une charpente de tétraèdres BO₄ et de triangles BO₃. Boracite orthorhombique à basse température, cubique au-dessus de 265 °C." },
    // ── sulfates, chromates, molybdates, tungstates (F.4 classe VII, 01/10/2026) ──
    barytine: { fichier: "barytine", polyedres: ["S"],
      note: "Baryums à douze oxygènes et tétraèdres SO₄ isolés. Maille en Pnma, comme les ouvrages la donnent." },
    celestine: { fichier: "celestine", polyedres: ["S"],
      note: "Structure de la barytine, où le strontium remplace le baryum." },
    anglesite: { fichier: "anglesite", polyedres: ["S"],
      note: "Structure de la barytine, où le plomb remplace le baryum. Maille en Pbnm (a et c des ouvrages échangés)." },
    epsomite: { fichier: "epsomite", polyedres: ["S", "Mg"],
      note: "Liaisons hydrogène : octaèdres Mg(H₂O)₆, tétraèdres SO₄ et une septième eau libre tiennent ensemble." },
    thenardite: { fichier: "thenardite", polyedres: ["S", "Na"],
      note: "Sans eau, des tétraèdres SO₄ isolés voisinent avec des sodiums entourés de six oxygènes de sulfate. Forme V, stable à température ordinaire." },
    mirabilite: { fichier: "mirabilite", polyedres: ["S", "Na"],
      note: "Ions sulfate, molécules d'eau et chaînes d'octaèdres Na(H₂O)₆ sont retenus par des liaisons hydrogène. Affinement aux neutrons." },
    chalcanthite: { fichier: "chalcanthite", polyedres: ["S"],
      note: "Quatre molécules d'eau forment un carré autour de chaque cuivre ; deux oxygènes de sulfate se trouvent plus loin, et une cinquième eau est libre. Affinement aux neutrons." },
    alunite: { fichier: "alunite", polyedres: ["S", "Al"],
      note: "Des tétraèdres SO₄ relient des feuillets d'octaèdres AlO₂(OH)₄, avec du potassium entre les feuillets." },
    schwertmannite: { fichier: "schwertmannite", polyedres: ["Fe"],
      note: "Modèle de Fernandez-Martinez et al. (2010), affiné sur une schwertmannite de la mine de Monte Romero (Espagne) : doubles chaînes d'octaèdres de fer en tunnels, comme l'akaganéite. Charpente du fer seule : les sulfates, dans les tunnels et en surface, n'ont pas pu être placés ; les oxygènes comptent aussi les OH. Deux octaèdres trop déformés ne sont pas dessinés." },
    jarosite: { fichier: "jarosite", polyedres: ["S", "Fe"],
      note: "Ici, du fer ferrique se substitue à l'aluminium dans la structure de l'alunite." },
    crocoite: { fichier: "crocoite", polyedres: ["Cr"],
      note: "C'est la structure de la monazite : tétraèdres CrO₄ isolés, plombs à neuf oxygènes." },
    wulfenite: { fichier: "wulfenite", polyedres: ["Mo"],
      note: "C'est la structure de la scheelite : tétraèdres MoO₄ isolés, plombs à huit oxygènes." },
    scheelite: { fichier: "scheelite", polyedres: ["W"],
      note: "Dans une maille quadratique (c ≈ 2,2 a), des tétraèdres WO₄ isolés voisinent avec des calciums à huit oxygènes." },
    wolframite: { fichier: "wolframite", polyedres: ["W", "Fe"],
      note: "Chaînes en zigzag d'octaèdres WO₆ et FeO₆ allongées selon c. Structure d'une wolframite ferrifère (Escobar et al. 1971) ; le manganèse peut remplacer le fer en toutes proportions." },
    // ── carbonates et nitrates (F.4 classe V, 01/10/2026) ──
    magnesite: { fichier: "magnesite", polyedres: ["C", "Mg"],
      note: "Structure de la calcite où le magnésium remplace le calcium : des plans de cations alternent avec des plans de triangles CO₃, et chaque magnésium occupe le centre d'un octaèdre d'oxygènes." },
    rhodochrosite: { fichier: "rhodochrosite", polyedres: ["C", "Mn"],
      note: "Structure de la calcite, où le manganèse remplace le calcium." },
    smithsonite: { fichier: "smithsonite", polyedres: ["C", "Zn"],
      note: "Structure de la calcite, où le zinc remplace le calcium : c'est la plus petite maille du groupe après la magnésite." },
    ankerite: { fichier: "ankerite", polyedres: ["C", "Ca", "Fe"],
      note: "Structure de type dolomite : des plans de calcium alternent avec des plans partagés entre fer et magnésium. Ankérite de composition Ca(Fe₀,₅₄Mg₀,₄₅)(CO₃)₂." },
    cerusite: { fichier: "cerusite", polyedres: ["C"],
      note: "Les triangles CO₃ s'empilent en colonnes dans l'aragonite, où chaque plomb est entouré de neuf oxygènes." },
    strontianite: { fichier: "strontianite", polyedres: ["C"],
      note: "Structure de l'aragonite, où le strontium remplace le calcium." },
    witherite: { fichier: "witherite", polyedres: ["C"],
      note: "Structure de l'aragonite, où le baryum remplace le calcium ; la maille est presque hexagonale (b ≈ a√3)." },
    malachite: { fichier: "malachite", polyedres: ["C"],
      note: "Des octaèdres de cuivre allongés (deux liaisons longues, effet Jahn-Teller) forment des chaînes selon c, reliées par les triangles CO₃ et les OH. Hydrogènes placés (neutrons)." },
    azurite: { fichier: "azurite", polyedres: ["C"],
      note: "Charpente où les cuivres, entourés de quatre oxygènes en carré (et d'un ou deux autres plus loin), sont reliés par les triangles CO₃ et les OH." },
    nitratine: { fichier: "nitratine", polyedres: ["N", "Na"],
      note: "Structure de la calcite, où le sodium remplace le calcium et les triangles NO₃ les CO₃." },
    nitre: { fichier: "nitre", polyedres: ["N"],
      note: "Structure de l'aragonite : le potassium remplace le calcium, et les triangles NO₃ les CO₃. Affinement aux neutrons à 25 °C." },
    // ── sulfures (F.4 classe II, 01/10/2026) ──
    chalcocite: { fichier: "chalcocite",
      note: "Empilement hexagonal compact presque parfait de soufres : les 96 cuivres de la maille se logent dans ses vides triangulaires, selon un arrangement si complexe que la maille est géante (chalcocite « basse », stable sous 103 °C). Au-delà, les cuivres se mettent en mouvement : presque un liquide de cuivre dans une charpente de soufre." },
    bornite: { fichier: "bornite",
      note: "Les soufres forment un réseau cubique à faces centrées. Cuivre et fer s'installent dans une partie des vides tétraédriques, et les vides restants s'ordonnent en surstructure : bornite « basse », orthorhombique. Tous les métaux sont notés Cu, faute de distinction entre fer et cuivre." },
    acanthite: { fichier: "acanthite",
      note: "Au-dessus de 173 °C, les argents voyagent librement dans un réseau cubique de soufres (argentite). Refroidi, le sulfure d'argent fige ses atomes sur des sites précis et devient monoclinique : c'est sa forme basse température." },
    pentlandite: { fichier: "pentlandite", polyedres: ["Fe"],
      note: "Un réseau cubique à faces centrées de soufres : les métaux occupent huit vides tétraédriques sur seize, par groupes de huit en petits cubes (Fe,Ni)₈ reliés, plus un vide octaédrique. Fer et nickel partagent les mêmes sites, dont la légende donne les proportions." },
    galene: { fichier: "galene", polyedres: ["Pb"], ligandsHors: false,
      note: "Le plomb se loge au centre d'un octaèdre de six soufres, comme dans le sel de cuisine. Les plans {100} restent neutres, d'où le clivage cubique parfait." },
    blende: { fichier: "blende", polyedres: ["Zn"],
      note: "Un tétraèdre de quatre soufres entoure chaque zinc, et réciproquement : c'est le diamant avec un atome sur deux remplacé. Le clivage dodécaédrique correspond aux plans {110}, où zinc et soufre alternent." },
    chalcopyrite: { fichier: "chalcopyrite", polyedres: ["Cu", "Fe"],
      note: "Dans la blende, cuivre et fer remplacent le zinc, en alternance : la maille, cubique, devient quadratique et deux fois plus haute (c ≈ 2 a). Chaque métal occupe un tétraèdre de soufres." },
    mackinawite: { fichier: "mackinawite", polyedres: ["Fe"],
      note: "Tétraèdres FeS₄ qui partagent leurs arêtes en feuillets carrés ⊥ c, empilés sans liaison forte entre eux. Les fers d'un feuillet sont à 2,60 Å, presque comme dans le fer métal : liaisons Fe–Fe dessinées. FeS de synthèse (Lennie et al. 1995)." },
    pyrrhotite: { fichier: "pyrrhotite", polyedres: ["Fe"],
      note: "Dans la nickéline, les fers se logent dans des octaèdres de soufres empilés en colonnes, mais un fer sur huit manque : Fe₇S₈. Ces sites vides s'ordonnent en maille monoclinique (pyrrhotite 4C), magnétique." },
    cinabre: { fichier: "cinabre",
      note: "Des chaînes hélicoïdales Hg-S-Hg-S (2,37 Å) tournent autour de c, avec trois mercures par tour. Comme dans le quartz, l'hélice existe dans les deux sens : les cristaux sont droits ou gauches." },
    covellite: { fichier: "covellite",
      note: "Feuillets empilés : couches de triangles CuS₃ et de tétraèdres CuS₄, séparées par des paires de soufre (S₂, 2,07 Å) où passe le clivage basal parfait." },
    nickeline: { fichier: "nickeline", polyedres: ["Ni"],
      note: "Famille « type NiAs » : arsenics en empilement hexagonal compact, nickels dans les vides octaédriques. Les octaèdres partagent leurs faces selon c, de sorte que deux nickels voisins ne sont distants que de 2,5 Å : la liaison est en partie métallique. L'affinement de 1988 a révélé une légère distorsion (maille orthorhombique)." },
    greigite: { fichier: "greigite", polyedres: ["Fe"],
      note: "Structure du spinelle (comme la magnétite), soufre à la place de l'oxygène : soufres en empilement cubique compact, un fer sur trois en tétraèdre (2,15 Å), deux sur trois en octaèdre (2,46 Å). Greigite de Californie (Skinner et al. 1964)." },
    marcassite: { fichier: "marcassite", polyedres: ["Fe"],
      note: "Même formule que la pyrite, mais autre arrangement : les octaèdres FeS₆ forment des colonnes d'arêtes partagées selon c, et les soufres s'apparient encore (2,21 Å)." },
    arsenopyrite: { fichier: "arsenopyrite", polyedres: ["Fe"],
      note: "Structure dérivée de celle de la marcassite : chaque paire de soufres y devient une paire arsenic-soufre, et les fers se rapprochent deux à deux (2,73 Å), ce qui rend la maille monoclinique. Cristal de La Roche-Balue (Loire-Atlantique), de composition FeAsS exacte." },
    stibine: { fichier: "stibine",
      note: "Des rubans (Sb₄S₆)ₙ, faits de pyramides SbS₃, s'étirent selon b ; seules des liaisons faibles les séparent. Ils expliquent les longs prismes striés selon b et le clivage parallèle aux rubans." },
    orpiment: { fichier: "orpiment",
      note: "Pyramides AsS₃ partageant leurs sommets, en feuillets plissés ; les feuillets ne tiennent que par des forces de van der Waals. Le clivage est donc parfait, et les lamelles sont souples comme du mica." },
    realgar: { fichier: "realgar",
      note: "Le réalgar se compose de molécules As₄S₄ en cages : un tétraèdre d'arsenics coiffé d'un carré de soufres. Ces molécules ne tiennent que par de faibles forces, si bien que la lumière brise lentement la cage et transforme le réalgar en poudre jaune (pararéalgar)." },
    molybdenite: { fichier: "molybdenite", polyedres: ["Mo"],
      note: "Feuillets S-Mo-S, chaque molybdène dans un prisme triangulaire de six soufres. Seules des forces de van der Waals les unissent : d'où un clivage parfait, un toucher gras et un usage de lubrifiant comparable à celui du graphite." },
    tetraedrite: { fichier: "tetraedrite",
      note: "Dans une charpente ouverte de type blende, on trouve des cuivres en tétraèdres et en triangles, des antimoines en pyramides SbS₃ et un soufre au centre d'un octaèdre de cuivres. Fer, zinc ou argent peuvent remplacer une partie du cuivre (sites partagés)." },
    bournonite: { fichier: "bournonite",
      note: "Pyramides SbS₃ et cuivres en tétraèdres ; les plombs sont entourés de sept à huit soufres. Quasi carrée (a ≈ b), la maille explique les macles répétées à 90° en « roue dentée »." },
    boulangerite: { fichier: "boulangerite",
      note: "Allongés selon c (8,1 Å), des rubans de plomb, d'antimoine et de soufre portent plusieurs sites partagés entre plomb et antimoine ; ce sont eux qui font les fibres de la boulangérite." },
    proustite: { fichier: "proustite",
      note: "Des argents liés à deux soufres relient des pyramides AsS₃ orientées dans le même sens selon c : le cristal est polaire, et le haut diffère du bas." },
    pyrargyrite: { fichier: "pyrargyrite",
      note: "Structure identique à celle de la proustite, avec de l'antimoine au lieu de l'arsenic : les deux « argents rouges » constituent une série." },
    graphite: { fichier: "graphite", repetition: [2, 2, 1] },
    diamant: { fichier: "diamant" },

    // ── éléments natifs (classe I, F.4, 01/10/2026) : pas de polyèdres ; vue compacte = rayons MÉTALLIQUES
    //    (rayon atomique en coordinence 12, Teatum, Gschneidner et Waber 1968), pas ioniques ──
    or_natif: { fichier: "or", polyedres: [], rayonsCompacts: { Au: 1.44 },
      note: "Un atome à chaque coin et au centre de chaque face : c'est la maille cubique à faces centrées. Chaque atome compte 12 voisins à 2,88 Å, ce qui réalise l'empilement le plus dense de sphères égales (74 % de l'espace)." },
    argent_natif: { fichier: "argent", polyedres: [], rayonsCompacts: { Ag: 1.44 },
      note: "L'argent adopte l'empilement de l'or, cubique à faces centrées, avec 12 voisins à 2,89 Å. Les deux métaux se mélangent en toutes proportions, ce qui produit l'électrum naturel." },
    cuivre_natif: { fichier: "cuivre", polyedres: [], rayonsCompacts: { Cu: 1.28 },
      note: "Maille cubique à faces centrées et 12 voisins à 2,56 Å. Les plans {111}, les plus denses, glissent facilement : cela explique la malléabilité de l'or, de l'argent et du cuivre." },
    platine_natif: { fichier: "platine", polyedres: [], rayonsCompacts: { Pt: 1.39 },
      note: "Empilement cubique à faces centrées, 12 voisins à 2,77 Å. Dans le platine naturel, le fer est presque toujours présent, parfois à quelques pour cent, parfois au-delà de 10 %, ainsi que d'autres platinoïdes." },
    // minéraux des météorites (B.5, 08/10/2026) — CIF dans le scratchpad de la session ; cohénite : 9014474 (le 9016182 de Lipson
    // et Petch, recopié avec deux signes faux, donne Fe–Fe 1,6 Å)
    taenite: { fichier: "taenite", polyedres: [], repetition: [2, 2, 2], rayonsCompacts: { Fe: 1.26, Ni: 1.24 },
      note: "La tétrataénite (COD 9010017, Clarke et Scott 1980) est la taénite ordonnée, avec des plans de fer et de nickel alternés, présente dans des météorites. La taénite ordinaire garde le même empilement cubique à faces centrées (12 voisins vers 2,53 Å), mais fer et nickel s'y mélangent au hasard ; cet ordre n'apparaît qu'en dessous de 320 °C et demande des millions d'années. Elle ne se rencontre donc que dans les météorites qui ont refroidi très lentement, comme Saint-Séverin (Tagai et Takeda 1995)." },
    troilite: { fichier: "troilite", polyedres: ["Fe"],
      note: "Structure de type nickéline, légèrement déformée : chaque fer est au centre d'un octaèdre de six soufres, et les octaèdres, empilés en colonnes, partagent leurs faces. Pas de fer manquant (FeS exact) : les moments magnétiques s'annulent, et un aimant ne l'attire pas, à la différence de la pyrrhotite." },
    schreibersite: { fichier: "schreibersite", polyedres: [], rayonsCompacts: { Fe: 1.26, P: 1.1 },
      note: "Neuf métaux (fer et nickel mêlés, 2,25 à 2,39 Å) entourent chaque phosphore, et ces métaux se touchent. Le modèle provient de la schreibersite de la météorite d'Acuña (Skala et Cisarova 2005)." },
    cohenite: { fichier: "cohenite", polyedres: ["C"], rayonsCompacts: { Fe: 1.26, C: 0.77 },
      note: "Comme dans la cémentite des aciers (Fe₃C), un carbone occupe le centre d'un prisme de six fers (≈ 2,0 Å) ; les prismes partagent leurs arêtes. Meinhardt et Krisement (1962) ont affiné cette structure aux neutrons, sur de la cémentite de synthèse." },
    moissanite: { fichier: "moissanite", polyedres: ["Si"], repetition: [2, 2, 1], vue: { axe: "a" },
      note: "Le polytype 6H, le plus fréquent, associe des tétraèdres de silicium et de carbone, à la façon du diamant ; ses couches se répètent tous les six plans (≈ 15 Å). Plus de 250 polytypes du SiC existent, différant seulement par cet ordre d'empilement." },
    oldhamite: { fichier: "oldhamite", polyedres: ["Ca"],
      note: "Structure de type halite (sel gemme) : chaque calcium occupe le centre d'un octaèdre de six soufres (2,85 Å), et réciproquement, d'où le clivage cubique." },
    daubreelite: { fichier: "daubreelite", polyedres: ["Cr", "Fe"],
      note: "Structure du spinelle, avec du soufre à la place de l'oxygène : le chrome dans des octaèdres de soufre (2,40 Å), le fer dans des tétraèdres (2,34 Å). Affinement sur un composé de synthèse (Raccah et al. 1966)." },
    merrillite: { fichier: "merrillite", polyedres: ["P", "Mg"],
      note: "Tétraèdres de phosphate isolés reliés par du calcium, du magnésium (octaèdres) et du sodium. Même charpente que la whitlockite terrestre, mais sans hydrogène : c'est la forme sèche, propre aux météorites et aux roches lunaires. Affinement sur la merrillite de la chondrite de Suizhou (Xie et al. 2015)." },
    fer_natif: { fichier: "fer", polyedres: [], rayonsCompacts: { Fe: 1.26 },
      note: "Fer α (kamacite des météorites) : maille cubique centrée, un atome à chaque coin et un au centre, avec 8 voisins à 2,48 Å. Plus lâche (68 %) que l'or ou le cuivre. Au-delà de 912 °C, le fer prend l'empilement cubique à faces centrées (fer γ, taénite des météorites)." },
    mercure_natif: { fichier: "mercure", mode: "compact", polyedres: [], rotation: true, rayonsCompacts: { Hg: 1.4 },
      note: "À l'état liquide, les atomes restent serrés (10 voisins vers 3 Å) mais sans ordre, et ils ne cessent de bouger : l'agitation dessinée n'est qu'un schéma. Le mercure ne cristallise qu'à −38,8 °C (maille rhomboédrique)." },
    arsenic_natif: { fichier: "arsenic", polyedres: [], repetition: [2, 2, 1], vue: { axe: "a" }, rayonsCompacts: { As: 1.21 },
      note: "Dans les couches plissées, chaque atome compte 3 voisins de sa couche (2,52 Å) ; les couches n'entrent en contact qu'à 3,12 Å, sans liaison forte. Le clivage parfait {0001} suit donc ces couches." },
    antimoine_natif: { fichier: "antimoine", polyedres: [], repetition: [2, 2, 1], vue: { axe: "a" }, rayonsCompacts: { Sb: 1.41 },
      note: "Structure en couches plissées, comme l'arsenic : 3 voisins dans chaque couche (2,91 Å), couches espacées de 3,36 Å. Le clivage parfait {0001} passe entre elles." },
    bismuth_natif: { fichier: "bismuth", polyedres: [], repetition: [2, 2, 1], vue: { axe: "a" }, rayonsCompacts: { Bi: 1.55 },
      note: "L'antimoine adopte la structure en couches plissées de l'arsenic : 3 voisins dans la couche (3,07 Å) et couches à 3,53 Å, d'où le clivage parfait {0001}." },
    soufre_natif: { fichier: "soufre", polyedres: [], molecules: true, rayonsCompacts: { S: 1.04 },
      note: "Le soufre α est un cristal moléculaire : des anneaux de 8 atomes (S₈) en couronne, liés entre eux par de simples forces de van der Waals (3,3 Å entre anneaux). D'où sa faible dureté (2) et sa fusion dès 115 °C. La maille compte 16 anneaux." },

    // ── composés organiques (classe X, F.6) : billes et liaisons ; polyèdres autour des seuls métaux ;
    //    molecules: true = molécules et ions organiques complétés au bord du bloc ──
    whewellite: { fichier: "whewellite", molecules: true, polyedres: ["Ca"],
      note: "Chacune de deux molécules d'eau de la maille se répartit entre deux positions voisines. Le dessin ne montre que la position la plus fréquente (85 %) ; l'affinement ne localise pas certains hydrogènes." },
    weddellite: { fichier: "weddellite", molecules: true, polyedres: ["Ca"],
      note: "L'eau des canaux (eau « zéolitique ») n'est présente que dans six cas sur dix environ. Ce surplus variable s'échappe lors de la transformation de la weddellite en whewellite." },
    caoxite: { fichier: "caoxite", molecules: true, polyedres: ["Ca"] },
    humboldtine: { fichier: "humboldtine", molecules: true, polyedres: ["Fe"], note: "Affinement sur l'oxalate ferreux synthétique." },
    lindbergite: { fichier: "lindbergite", molecules: true, polyedres: ["Mn"],
      note: "Affinement réalisé sur le composé synthétique : la structure est identique à celle de la humboldtine, le manganèse occupant la place du fer." },
    natroxalate: { fichier: "natroxalate", molecules: true, polyedres: ["Na"], note: "Affinement effectué sur l'oxalate de sodium synthétique." },
    oxammite: { fichier: "oxammite", molecules: true, polyedres: [] },
    minguzzite: { fichier: "minguzzite", molecules: true, polyedres: ["Fe"], note: "Structure établie sur le ferrioxalate de potassium synthétique (Herpin, 1958) ; l'emplacement des hydrogènes n'a pas été déterminé." },
    wheatleyite: { fichier: "wheatleyite", molecules: true, polyedres: ["Cu"], note: "Affinement sur un composé synthétique ; les atomes d'hydrogène ne sont pas placés." },
    novgorodovaite: { fichier: "novgorodovaite", molecules: true, polyedres: ["Ca"] },
    coskrenite_ce: { fichier: "coskrenite_ce", molecules: true, polyedres: ["S"],
      note: "Le cérium, le néodyme, le lanthane et les autres terres rares occupent un même site : la bille figure l'élément majoritaire." },
    levinsonite_y: { fichier: "levinsonite_y", molecules: true, polyedres: ["Al", "S"],
      note: "L'yttrium et les terres rares se répartissent sur un même site ; la bille représente l'élément dominant." },
    zugshunstite_ce: { fichier: "zugshunstite_ce", molecules: true, polyedres: ["Al", "S"] },
    deveroite_ce: { fichier: "deveroite_ce", molecules: true, polyedres: [],
      note: "Résultat obtenu sur l'oxalate de cérium synthétique (Ollendorff et Weigel, 1969) ; les hydrogènes des molécules d'eau restent non localisés." },
    dashkovaite: { fichier: "dashkovaite", molecules: true, polyedres: ["Mg"],
      note: "Structure du formiate de magnésium synthétique, dont les hydrogènes n'ont pas été localisés." },
    calclacite: { fichier: "calclacite", molecules: true, polyedres: [], note: "Affinement sur un composé synthétique ; les atomes d'hydrogène ne sont pas placés." },
    hoganite: { fichier: "hoganite", molecules: true, polyedres: [],
      note: "Affinement effectué sur l'acétate de cuivre synthétique. Les atomes de cuivre forment des paires, pontées chacune par quatre acétates : cet agencement en « roue à aubes » est caractéristique de la chimie de coordination." },
    paceite: { fichier: "paceite", molecules: true, polyedres: ["Cu"],
      note: "Les atomes d'hydrogène des groupes méthyle adoptent deux orientations ; une seule est représentée." },
    ernstburkeite: { fichier: "ernstburkeite", molecules: true, polyedres: ["Mg"],
      note: "Structure affinée sur un composé synthétique de formule Mg(CH₃SO₃)₂·12H₂O." },
    mellite: { fichier: "mellite", molecules: true, polyedres: ["Al"],
      note: "Diffraction de neutrons à 15 K sur un cristal de Tatabánya (Robl et Kuhs, 1991) : l'ensemble des hydrogènes est localisé. Les ions mellitate, cycles plats portant six groupes acides, alternent avec des octaèdres Al(H₂O)₆ ; la cohésion de l'édifice repose sur des liaisons hydrogène." },
    julienite: { fichier: "julienite", molecules: true, polyedres: ["Co"], note: "Affinement sur un composé synthétique ; les hydrogènes ne sont pas placés. Chaque cobalt est coordonné à quatre ions thiocyanate par leur azote : cet environnement à quatre voisins explique sa couleur bleue." },
    fichtelite: { fichier: "fichtelite", molecules: true, polyedres: [] },
    branchite: { fichier: "branchite", molecules: true, polyedres: [], note: "Les hydrogènes ne sont pas placés dans cet affinement (Bouška et al. 1998, sous le nom de hartite)." },
    simonellite: { fichier: "simonellite", molecules: true, polyedres: [], note: "Affinement sur un composé synthétique ; les atomes d'hydrogène ne sont pas placés." },
    kratochvilite: { fichier: "kratochvilite", molecules: true, polyedres: [], note: "Affinement sur le fluorène synthétique." },
    ravatite: { fichier: "ravatite", molecules: true, polyedres: [], note: "Phénanthrène synthétique : affinement sans localisation des atomes d'hydrogène." },
    carpathite: { fichier: "carpathite", molecules: true, polyedres: [],
      note: "Des molécules planes de coronène s'empilent en colonnes inclinées, espacées de 3,46 Å." },
    hoelite: { fichier: "hoelite", molecules: true, polyedres: [], note: "Structure de l'anthraquinone (affinement de 1967)." },
    kladnoite: { fichier: "kladnoite", molecules: true, polyedres: [], note: "Structure du phtalimide (Matzat 1972)." },
    flagstaffite: { fichier: "flagstaffite", molecules: true, polyedres: [], note: "L'hydrate de terpine a été décrit structuralement par Marsh et Herbstein (1988)." },
    abelsonite: { fichier: "abelsonite", molecules: true, polyedres: [],
      note: "La molécule, non symétrique, se place au hasard dans deux orientations autour du nickel : la structure affichée superpose les positions les plus occupées de ses groupes latéraux (Hummer et al. 2017). Le cycle central, lui, est ordonné." },
    urea: { fichier: "urea", molecules: true, polyedres: [], note: "Affinement sur l'urée synthétique, par diffraction de neutrons." },
    uricite: { fichier: "uricite", molecules: true, polyedres: [], note: "Affinement sur l'acide urique synthétique." },
    allantoin: { fichier: "allantoin", molecules: true, polyedres: [], note: "Affinement sur de l'allantoïne extraite d'un lichen comestible (Xu et al. 2011)." },
    // ── tectosilicates et zéolithes (F.4 classes IX.F–IX.G, 01/10/2026) : charpentes de tétraèdres ; l'eau des zéolithes = « Ow » ──
    tridymite: { fichier: "tridymite", polyedres: ["Si"],
      note: "La tridymite MC (monoclinique) est la forme stable à température ambiante. Ses feuillets de tétraèdres SiO₄ forment des anneaux à six membres, dont les pointes alternent vers le haut et vers le bas ; l'empilement se fait par deux couches, contrairement au quartz et à la cristobalite." },
    cristobalite: { fichier: "cristobalite", polyedres: ["Si"],
      note: "L'α-cristobalite (quadratique) présente des feuillets de tétraèdres en anneaux à six membres, empilés par trois couches et légèrement inclinés. Au-delà d'environ 250 °C, ces feuillets se redressent et la maille devient cubique." },
    moganite: { fichier: "moganite", polyedres: ["Si"],
      note: "Une alternance régulière de tranches de quartz droit et gauche, le long de a, donne un quartz maclé à l'échelle de la maille." },
    stishovite: { fichier: "stishovite", polyedres: ["Si"],
      note: "Dans la structure du rutile, le silicium est entouré de six oxygènes (octaèdres en chaînes le long de c), coordinence rare à la surface ; il en résulte une densité de 4,3." },
    seifertite: { fichier: "seifertite", polyedres: ["Si"],
      note: "Des octaèdres SiO₆ forment des chaînes en zigzag, selon la structure de l'α-PbO₂ : ils sont plus compacts encore que ceux de la stishovite." },
    melanophlogite: { fichier: "melanophlogite", polyedres: ["Si"],
      note: "Clathrate de silice : charpente de tétraèdres délimitant des cages (dodécaèdres et tétrakaidécaèdres), sur le modèle de la glace des hydrates de gaz ; les cages renferment du méthane et du CO₂ (C au centre, H non placés)." },
    anorthose: { fichier: "anorthose", polyedres: ["Si","Al"],
      note: "Feldspath sodi-potassique triclinique : la charpente est celle de l'albite, le sodium et le potassium se partageant un même site (désordre Al/Si, structure moyenne)." },
    celsiane: { fichier: "celsiane", polyedres: ["Si","Al"],
      note: "Dans la charpente feldspathique, aluminium et silicium s'ordonnent strictement (Al₂Si₂), ce qui double la maille c (14,4 Å). Le baryum loge dans les cavités." },
    hyalophane: { fichier: "hyalophane", polyedres: ["Si","Al"],
      note: "Entre la sanidine et le celsiane, les sites des cavités sont partagés par le baryum, le potassium et le sodium." },
    oligoclase: { fichier: "oligoclase", polyedres: ["Si","Al"],
      note: "Plagioclase An≈18 : la charpente est celle de l'albite, le sodium et un peu de calcium occupant un même site." },
    bytownite: { fichier: "bytownite", polyedres: ["Si","Al"],
      note: "Plagioclase An85 : la maille c est doublée (14,2 Å), comme celle de l'anorthite ; l'aluminium et le silicium sont presque ordonnés." },
    kalsilite: { fichier: "kalsilite", polyedres: ["Si","Al"],
      note: "La charpente de la tridymite présente une alternance ordonnée entre aluminium et silicium, le potassium logeant dans les canaux : il s'agit d'un feldspathoïde très pauvre en silice." },
    sodalite: { fichier: "sodalite", polyedres: ["Si","Al"],
      note: "Un réseau cubique de cages de 24 tétraèdres (cuboctaèdres tronqués) ; le centre de chaque cage porte un Cl⁻ entouré de quatre Na⁺." },
    hauyne: { fichier: "hauyne", polyedres: ["Si","Al","S"],
      note: "Dans les cages de la sodalite, environ un sulfate SO₄²⁻ accompagne Na, Ca et K (positions moyennes et désordonnées)." },
    noseane: { fichier: "noseane", polyedres: ["Si","Al","S"],
      note: "Les cages de la sodalite renferment du sulfate et du sodium ; l'eau, à raison de moins d'une molécule par cage, n'est pas placée." },
    lazurite: { fichier: "lazurite", polyedres: ["Si","Al","S"],
      note: "Structure moyenne (la structure réelle est modulée) : cages de la sodalite contenant du sulfate et du sodium. Les ions polysulfure S₃⁻, responsables du bleu, sont trop désordonnés pour être représentés." },
    cancrinite: { fichier: "cancrinite", polyedres: ["Si","Al"],
      note: "Des anneaux à six tétraèdres s'empilent par deux couches, formant de larges canaux le long de c. Ces canaux renferment du Na, du Ca et des carbonates (orientations moyennes)." },
    davyne: { fichier: "davyne", polyedres: ["Si","Al"],
      note: "Les canaux de la cancrinite accueillent des chaînes Ca-Cl et des sulfates, tandis que ses cavités renferment K et Na." },
    vishnevite: { fichier: "vishnevite", polyedres: ["Si","Al","S"],
      note: "La cancrinite, dont les carbonates sont substitués par des sulfates et de l'eau, présente la même charpente." },
    afghanite: { fichier: "afghanite", polyedres: ["Si","Al","S"],
      note: "L'empilement comprend huit couches d'anneaux à six tétraèdres (c = 21,4 Å) où se succèdent cages de sodalite et de cancrinite, renfermant sulfates et chlore." },
    tugtupite: { fichier: "tugtupite", polyedres: ["Si","Al","Be"],
      note: "Le béryllium et l'aluminium se substituent en partie, et de manière ordonnée, au silicium de la charpente de sodalite ; un Cl⁻ occupe le centre des cages." },
    marialite: { fichier: "marialite", polyedres: ["Si","Al"],
      note: "Les anneaux de quatre tétraèdres de la scapolite s'agencent en colonnes parallèles à c ; un Cl⁻, entouré de Na⁺, occupe chaque grande cavité." },
    meionite: { fichier: "meionite", polyedres: ["Si","Al"],
      note: "Scapolite calcique (Me80) : même charpente que la marialite, un carbonate CO₃²⁻ occupe le centre des cavités, entouré de calcium (désordre d'orientation)." },
    silvialite: { fichier: "silvialite", polyedres: ["Si","Al","S"],
      note: "Dans la scapolite sulfatée, la charpente reprend celle de la méionite : un sulfate SO₄²⁻, accompagné parfois de CO₃²⁻, s'installe au centre des cavités." },
    danburite: { fichier: "danburite", polyedres: ["Si","B"],
      note: "Des paires Si₂O₇ et des groupes B₂O₇ (tétraèdres de bore) forment la charpente ; le calcium remplit les cavités, sur un plan semblable à celui de l'anorthite." },
    petalite: { fichier: "petalite", polyedres: ["Si","Al","Li"],
      note: "Plusieurs feuillets de tétraèdres SiO₄, plissés, sont unis par des tétraèdres AlO₄ et LiO₄ ; la structure se clive donc selon ces feuillets." },
    leifite: { fichier: "leifite", polyedres: ["Si","Al","Be"],
      note: "Une charpente de tétraèdres (Si, Al, Be), trouée de canaux parallèles à c, abrite Na, K et de l'eau (non placée)." },
    natrolite: { fichier: "natrolite", polyedres: ["Si","Al"],
      note: "Zéolithe fibreuse : des chaînes de tétraèdres s'étendent le long de c, par unités de cinq tétraèdres, et se relient latéralement. Les canaux en zigzag contiennent du Na⁺ et de l'eau." },
    mesolite: { fichier: "mesolite", polyedres: ["Si","Al"],
      note: "Charpente de la natrolite. Les canaux renferment alternativement du Na, comme dans la natrolite, et du Ca, comme dans la scolécite, ce qui triple la maille selon b. L'eau est représentée avec ses hydrogènes (neutrons)." },
    scolecite: { fichier: "scolecite", polyedres: ["Si","Al"],
      note: "Un Ca²⁺ remplace 2 Na⁺ dans la charpente de la natrolite, et une molécule d'eau de plus vient s'ajouter ; la symétrie, abaissée, est monoclinique." },
    thomsonite: { fichier: "thomsonite", polyedres: ["Si","Al"],
      note: "Les chaînes de la natrolite sont reliées autrement ; l'aluminium et le silicium alternent strictement. L'eau est représentée avec ses hydrogènes." },
    gonnardite: { fichier: "gonnardite", polyedres: ["Si","Al"],
      note: "Charpente de la natrolite dans laquelle l'aluminium et le silicium sont désordonnés : la maille est quadratique (« tétranatrolite »)." },
    edingtonite: { fichier: "edingtonite", polyedres: ["Si","Al"],
      note: "Les chaînes de la natrolite forment une charpente quadratique ; du baryum et de l'eau occupent les canaux." },
    chabazite: { fichier: "chabazite", polyedres: ["Si","Al"],
      note: "Des doubles anneaux à six tétraèdres s'empilent en rhomboèdre : ils délimitent de grandes cages (6,7 × 10 Å) ouvertes par des fenêtres à huit tétraèdres, où logent Ca, Na et de l'eau." },
    levyne: { fichier: "levyne", polyedres: ["Si","Al"],
      note: "Des anneaux simples et doubles à six tétraèdres s'empilent autrement que dans la chabazite, formant des cages aplaties ; les cations et l'eau y occupent des positions partielles." },
    erionite: { fichier: "erionite", polyedres: ["Si","Al"],
      note: "Cages de cancrinite et doubles anneaux de six tétraèdres s'enchaînent le long de c et délimitent de vastes cavités. C'est la forme fibreuse de l'érionite qui rend ses poussières dangereuses (mésothéliome)." },
    faujasite: { fichier: "faujasite", polyedres: ["Si","Al"],
      note: "Les cages de sodalite se relient par des doubles anneaux à six, comme les atomes de carbone du diamant ; elles forment des « supercages » de 13 Å, les plus vastes parmi les zéolithes naturelles (Baur, 1964)." },
    heulandite: { fichier: "heulandite", polyedres: ["Si","Al"],
      note: "Parallèlement à (010), des couches denses de tétraèdres ne se rejoignent que par peu de liaisons ; dans le plan s'ouvrent des canaux à dix et huit tétraèdres, ce qui explique le clivage parfait {010}." },
    clinoptilolite: { fichier: "clinoptilolite", polyedres: ["Si","Al"],
      note: "La charpente de la heulandite est plus riche en silicium (Si/Al > 4), ce qui la rend plus stable à la chaleur. Ca, Na, K, Mg et l'eau occupent les canaux, en positions partielles." },
    stilbite: { fichier: "stilbite", polyedres: ["Si","Al"],
      note: "Des couches de tétraèdres parallèles à (010) s'assemblent en charpente ; le long de a, de vastes canaux à dix tétraèdres accueillent Ca, Na et l'eau (Slaughter, 1970)." },
    stellerite: { fichier: "stellerite", polyedres: ["Si","Al"],
      note: "Stilbite dépourvue de sodium : symétrie orthorhombique." },
    barrerite: { fichier: "barrerite", polyedres: ["Si","Al"],
      note: "Stilbite sodique : la symétrie est orthorhombique (Amma)." },
    brewsterite: { fichier: "brewsterite", polyedres: ["Si","Al"],
      note: "Les canaux, formés de huit tétraèdres, abritent des strontiums ; chacun est coordonné par des oxygènes de la charpente et par cinq molécules d'eau. Le secteur triclinique étudié provient d'un cristal à secteurs (Akizuki, 1996)." },
    epistilbite: { fichier: "epistilbite", polyedres: ["Si","Al"],
      note: "Des canaux bordés de dix et huit tétraèdres accueillent calcium et eau. L'affinement est dû à Perrotta (1967)." },
    analcime: { fichier: "analcime", polyedres: ["Si","Al"],
      note: "Anneaux de quatre et de six tétraèdres organisés en charpente cubique ; chaque canal renferme un Na⁺ et une molécule d'eau. Cette charpente est celle de la leucite et de la pollucite." },
    laumontite: { fichier: "laumontite", polyedres: ["Si","Al"],
      note: "Dans les canaux de dix tétraèdres parcourant c, calcium et eau prennent place ; à l'air sec, une partie de l'eau s'échappe et le minéral s'effrite (variété « léonhardite »)." },
    phillipsite: { fichier: "phillipsite", polyedres: ["Si","Al"],
      note: "Doubles chaînes en forme de vilebrequin, assemblées en charpente ; K, Na et Ca occupent des canaux qui se recoupent." },
    harmotome: { fichier: "harmotome", polyedres: ["Si","Al"],
      note: "Dans la charpente de la phillipsite, le baryum se substitue au potassium." },
    amicite: { fichier: "amicite", polyedres: ["Si","Al"],
      note: "Chez la gismondine, aluminium et silicium s'alternent strictement, et K et Na s'ordonnent dans les canaux." },
    pollucite: { fichier: "pollucite", polyedres: ["Si","Al"],
      note: "Charpente de l'analcime : le césium, atome volumineux, occupe le site de la molécule d'eau (site partagé Cs/eau)." },
    hsianghualite: { fichier: "hsianghualite", polyedres: ["Si","Be","Li"],
      note: "Charpente cubique de tétraèdres SiO₄, BeO₄ et LiO₃F, sur le modèle de l'analcime ; les cavités accueillent calcium et fluor." },
  });
})();
